package com.countryguard.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.graphics.Color;
import android.view.*;
import android.widget.*;
import java.util.*;
import static com.countryguard.app.DecisionTree.*;
import static com.countryguard.app.ProtectionPolicy.Action.*;

public final class RulesActivity extends Activity {
    private Node root; private boolean sms; private TreeStore store; private TreeCanvas canvas;
    private TextView status; private String saved; private final ArrayDeque<String> undo=new ArrayDeque<>();
    private SettingsStore settings;
    @Override public void onCreate(Bundle state){super.onCreate(state);sms=getIntent().getBooleanExtra("sms",false);store=new TreeStore(this);settings=new SettingsStore(this);
        root=store.load(sms);saved=TreeStore.encode(root);if(state!=null){root=TreeStore.decode(state.getString("draft",saved));saved=state.getString("saved",saved);ArrayList<String> history=state.getStringArrayList("undo");if(history!=null)undo.addAll(history);}
        LinearLayout shell=column();shell.setBackgroundColor(0xfff1f5f4);shell.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets b=Build.VERSION.SDK_INT>=30?i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout()):i.getSystemWindowInsets();v.setPadding(b.left,b.top,b.right,b.bottom);return i;});
        LinearLayout header=new LinearLayout(this);shell.addView(header);button(header,"‹",this::leave);TextView heading=text(sms?"SMS decision tree":"Call decision tree",22);heading.setTypeface(null,android.graphics.Typeface.BOLD);header.addView(heading,new LinearLayout.LayoutParams(0,-2,1));button(header,"Save",this::save);
        status=text("",13);shell.addView(status);refreshStatus();
        LinearLayout tools=new LinearLayout(this);shell.addView(tools);button(tools,"Undo",this::undo);button(tools,"Example",this::example);button(tools,"Test",this::test);button(tools,"⋮",this::menu);
        canvas=new TreeCanvas(this,sms,this::edit);shell.addView(canvas,new LinearLayout.LayoutParams(-1,0,1));canvas.tree(root,true);
        LinearLayout bottom=new LinearLayout(this);shell.addView(bottom);button(bottom,"−",()->canvas.zoom(.8f));button(bottom,"Fit",()->canvas.fit());button(bottom,"+",()->canvas.zoom(1.25f));TextView hint=text("Tap a node to edit\nDrag / pinch to explore",12);bottom.addView(hint);
        setContentView(shell);shell.requestApplyInsets();if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(0,this::leave);
        if(getIntent().getBooleanExtra("test",false))shell.post(this::test);
    }
    @Override protected void onSaveInstanceState(Bundle b){b.putString("draft",TreeStore.encode(root));b.putString("saved",saved);b.putStringArrayList("undo",new ArrayList<>(undo));super.onSaveInstanceState(b);}
    @SuppressWarnings("deprecation") @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){leave();}
    private void leave(){if(TreeStore.encode(root).equals(saved)){finish();return;}new AlertDialog.Builder(this).setTitle("Unsaved tree").setMessage("Your saved tree is still in use.").setNegativeButton("Keep editing",null).setNeutralButton("Discard",(d,w)->finish()).setPositiveButton("Save & close",(d,w)->{if(save())finish();}).show();}
    private boolean save(){try{store.save(sms,root);saved=TreeStore.encode(root);refreshStatus();Toast.makeText(this,"Tree saved",Toast.LENGTH_SHORT).show();return true;}catch(RuntimeException e){error(e.getMessage());return false;}}
    private void refreshStatus(){boolean enabled=sms?settings.flag("smsEnabled"):settings.enabled();android.app.role.RoleManager role=getSystemService(android.app.role.RoleManager.class);boolean ready=role!=null&&role.isRoleHeld(sms?android.app.role.RoleManager.ROLE_SMS:android.app.role.RoleManager.ROLE_CALL_SCREENING);status.setText((TreeStore.encode(root).equals(saved)?"SAVED":"UNSAVED CHANGES")+"  ·  "+(!ready?"Setup needed on home screen":enabled?"Filtering on":"Filtering paused"));status.setTextColor(0xff416359);}
    private void checkpoint(){undo.push(TreeStore.encode(root));while(undo.size()>1&&(undo.size()>30||undo.stream().mapToInt(String::length).sum()>80000))undo.removeLast();}
    private void changed(boolean fit){try{validate(root,sms);}catch(IllegalArgumentException e){root=TreeStore.decode(undo.pop());error(e.getMessage());}clearDescriptions(root);canvas.tree(root,fit);refreshStatus();}
    private void clearDescriptions(Node n){n.reason="";n.legacyStage=-1;if(n.kind!=Kind.OUTCOME){clearDescriptions(n.yes);clearDescriptions(n.no);}}
    private void undo(){if(!undo.isEmpty()){root=TreeStore.decode(undo.pop());canvas.tree(root,true);refreshStatus();}}
    private void edit(Node n){String[] choices=n.kind==Kind.OUTCOME?new String[]{"Add a decision here","Change outcome"}:new String[]{"Edit condition","Change condition type","Swap Yes and No","Remove decision · keep Yes branch","Remove decision · keep No branch","Replace subtree with outcome","Insert a decision before this"};
        new AlertDialog.Builder(this).setTitle(display(n)).setItems(choices,(d,w)->{if(n.kind==Kind.OUTCOME){if(w==0)chooseKind(n,true);else outcome(n);}else switch(w){case 0->configure(n);case 1->chooseKind(n,false);case 2->{checkpoint();Node t=n.yes;n.yes=n.no;n.no=t;changed(false);}case 3->remove(n,true);case 4->remove(n,false);case 5->outcome(n);case 6->chooseKind(n,true);}}).setNegativeButton("Close",null).show();
    }
    private void remove(Node n,boolean yes){new AlertDialog.Builder(this).setTitle("Remove this decision?").setMessage("Keep the "+(yes?"Yes":"No")+" branch and discard the other branch.").setNegativeButton("Cancel",null).setPositiveButton("Remove",(d,w)->{checkpoint();root=replace(root,n.id,yes?n.yes:n.no);changed(true);}).show();}
    private void outcome(Node n){String[] labels=sms?new String[]{"Inbox","Filtered"}:new String[]{"Allow","Block","Silence"};new AlertDialog.Builder(this).setTitle(n.kind==Kind.OUTCOME?"Choose outcome":"Replace this entire subtree?").setItems(labels,(d,w)->{checkpoint();root=replace(root,n.id,DecisionTree.outcome(w==0?ALLOW:w==1?BLOCK:SILENCE));changed(true);}).setNegativeButton("Cancel",null).show();}
    private void chooseKind(Node n,boolean insert){ArrayList<Kind> kinds=new ArrayList<>(Arrays.asList(Kind.CONTACT,Kind.NON_CONTACT,Kind.TIME,Kind.COUNTRY,Kind.NUMBERS,Kind.PREFIX,Kind.TEMPORARY));if(!sms)kinds.add(Kind.REPEAT);else{kinds.add(Kind.LINK);kinds.add(Kind.PHRASE);}String[] labels=kinds.stream().map(k->title(new Node(k))).toArray(String[]::new);
        new AlertDialog.Builder(this).setTitle("Choose a decision").setItems(labels,(d,w)->{checkpoint();Node next=insert?decision(kinds.get(w),TreeStore.copy(n),TreeStore.copy(n)):TreeStore.copy(n);next.kind=kinds.get(w);next.reason="";next.legacyStage=-1;root=replace(root,n.id,next);changed(true);configure(next);}).setNegativeButton("Cancel",null).show();
    }
    private void configure(Node n){switch(n.kind){
        case COUNTRY->countries(n);
        case NUMBERS,PREFIX,PHRASE->values(n);
        case TIME->time(n);
        case REPEAT->repeat(n);
        case TEMPORARY->temporary();
        case CONTACT,NON_CONTACT->new AlertDialog.Builder(this).setTitle(title(n)).setMessage("Contacts are numbers saved in your phone address book. This decision takes Yes only when Contacts access confirms the answer. If access is unavailable it takes No. Android may exclude saved contacts from screening without this permission.").setNegativeButton("Close",null).setPositiveButton("Grant Contacts access",(d,w)->requestPermissions(new String[]{android.Manifest.permission.READ_CONTACTS},42)).show();
        case LINK->new AlertDialog.Builder(this).setTitle("Message contains a link?").setMessage("Yes when the text contains a web address. The Yes and No branches determine what happens next.").setPositiveButton("Close",null).show();
        default->{}
    }}
    private void countries(Node n){LinearLayout box=column();Switch inverse=new Switch(this);inverse.setText("Match countries outside my selection");inverse.setChecked(n.outside);box.addView(inverse);TextView note=text("Off: Yes = in selection. On: Yes = outside, including unidentified countries.",13);box.addView(note);EditText search=input(box,"Search country or calling code","");ScrollView scroll=new ScrollView(this);LinearLayout list=column();scroll.addView(list);box.addView(scroll,new LinearLayout.LayoutParams(-1,dp(300)));Set<String> chosen=new TreeSet<>(n.values);
        ArrayList<String> regions=new ArrayList<>(com.google.i18n.phonenumbers.PhoneNumberUtil.getInstance().getSupportedRegions());regions.sort(Comparator.comparing(iso->new Locale("",iso).getDisplayCountry()));
        Runnable fill=()->{list.removeAllViews();String q=search.getText().toString().toLowerCase(Locale.ROOT);for(String iso:regions){String name=new Locale("",iso).getDisplayCountry()+"  +"+com.google.i18n.phonenumbers.PhoneNumberUtil.getInstance().getCountryCodeForRegion(iso);if(!(name+iso).toLowerCase(Locale.ROOT).contains(q))continue;CheckBox cb=new CheckBox(this);cb.setText(name);cb.setMinHeight(dp(48));cb.setChecked(chosen.contains(iso));cb.setOnCheckedChangeListener((v,on)->{if(on)chosen.add(iso);else chosen.remove(iso);});list.addView(cb);}};
        search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void afterTextChanged(android.text.Editable e){}public void onTextChanged(CharSequence s,int a,int b,int c){fill.run();}});fill.run();
        dialog("Countries for this decision",box,()->{checkpoint();n.values=chosen;n.outside=inverse.isChecked();changed(false);});
    }
    private void values(Node n){LinearLayout box=column();box.addView(text(n.kind==Kind.PREFIX?"One international prefix per line, e.g. +44":n.kind==Kind.PHRASE?"One phrase per line. Matches anywhere, ignoring case.":"One full phone number per line with +country code. SMS also supports sender names and short codes.",14));EditText entries=input(box,"One entry per line",String.join("\n",n.values));entries.setSingleLine(false);entries.setMinLines(4);entries.setMaxLines(8);
        AlertDialog d=new AlertDialog.Builder(this).setTitle(title(n)).setView(box).setNegativeButton("Cancel",null).setPositiveButton("Apply",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(v2->{Set<String> result=new TreeSet<>();for(String line:entries.getText().toString().split("\\R")){String value=line.trim();if(value.isEmpty())continue;if(n.kind==Kind.PREFIX){value=ProtectionPolicy.prefix(value);if(value==null){entries.setError("Use a +country prefix, e.g. +44");return;}}else if(n.kind==Kind.NUMBERS){String norm=new RuleEngine().normalizeException(value,settings.homeRegion());if(norm!=null)value=norm;else if(!sms){entries.setError("Use complete phone numbers with +country code");return;}else value=ProtectionPolicy.senderKey(value);}result.add(value);}checkpoint();n.values=result;changed(false);d.dismiss();}));d.show();
    }
    private void time(Node n){LinearLayout box=column();int[] times={n.start,n.end};Switch outside=new Switch(this);outside.setText("Match outside these hours");outside.setChecked(n.outside);box.addView(outside);Button a=button(box,"Start: "+clock(times[0]),()->{}),b=button(box,"End: "+clock(times[1]),()->{});a.setOnClickListener(v->new TimePickerDialog(this,(p,h,m)->{times[0]=h*60+m;a.setText("Start: "+clock(times[0]));},times[0]/60,times[0]%60,true).show());b.setOnClickListener(v->new TimePickerDialog(this,(p,h,m)->{times[1]=h*60+m;b.setText("End: "+clock(times[1]));},times[1]/60,times[1]%60,true).show());box.addView(text("Every day, in phone local time. Overnight ranges work. Equal start and end means all day. Start is included; end is excluded.",13));dialog("Time condition",box,()->{checkpoint();n.start=times[0];n.end=times[1];n.outside=outside.isChecked();changed(false);});}
    private void repeat(Node n){LinearLayout box=column();box.addView(text("Yes when earlier attempts reach the limit. The incoming call is the next attempt.",14));NumberPicker limit=new NumberPicker(this),window=new NumberPicker(this);limit.setMinValue(1);limit.setMaxValue(99);limit.setValue(n.limit);window.setMinValue(1);window.setMaxValue(60);window.setValue(n.window);box.addView(text("Earlier attempts",13));box.addView(limit);box.addView(text("Within this many minutes",13));box.addView(window);dialog("Repeated calls",box,()->{checkpoint();n.limit=limit.getValue();n.window=window.getValue();changed(false);});}
    private void temporary(){LinearLayout box=column();box.addView(text("This condition checks a shared expiry list. Changes to this list apply immediately. A permission has an effect only where a tree contains this condition.",14));EditText number=input(box,"Number with +country code","");for(var e:settings.temporaryNumbers().entrySet())box.addView(text(e.getKey()+" · "+java.text.DateFormat.getDateTimeInstance().format(new Date(e.getValue())),13));dialog("Temporary permission · 1 hour",box,()->{String norm=new RuleEngine().normalizeException(number.getText().toString(),settings.homeRegion());if(norm==null){error("Enter a complete phone number");return;}settings.temporary(norm,System.currentTimeMillis()+3600000L);});}
    private void example(){new AlertDialog.Builder(this).setTitle("Replace draft with an example").setItems(new String[]{"Allow contacts; block others outside 08:00–18:00","Country branches inside and outside working hours","Start over: "+(sms?"Inbox":"Allow")},(d,w)->{checkpoint();if(w==2)root=DecisionTree.outcome(ALLOW);else{Node time=decision(Kind.TIME,DecisionTree.outcome(ALLOW),DecisionTree.outcome(BLOCK));if(w==1){Node yes=decision(Kind.COUNTRY,DecisionTree.outcome(ALLOW),DecisionTree.outcome(BLOCK));yes.values.add(settings.homeRegion());Node no=decision(Kind.CONTACT,DecisionTree.outcome(ALLOW),DecisionTree.outcome(BLOCK));time.yes=yes;time.no=no;root=time;}else root=decision(Kind.CONTACT,DecisionTree.outcome(ALLOW),time);}changed(true);}).setNegativeButton("Cancel",null).show();}
    private void menu(){new AlertDialog.Builder(this).setTitle("Tree options").setItems(new String[]{"Turn filtering "+((sms?settings.flag("smsEnabled"):settings.enabled())?"off":"on"),"How to edit","Contacts permission"},(d,w)->{if(w==0){if(sms)settings.flag("smsEnabled",!settings.flag("smsEnabled"));else settings.setEnabled(!settings.enabled());refreshStatus();}else if(w==1)RuleHelp.show(this,sms);else requestPermissions(new String[]{android.Manifest.permission.READ_CONTACTS},42);}).show();}
    private void test(){LinearLayout box=column();EditText number=input(box,sms?"Sender":"Phone number with +country code","");EditText body=sms?input(box,"Message text",""):null;EditText at=input(box,"Time HH:mm",clock(TreePolicy.minute()));TextView result=text("Tests this draft. The highlighted route shows the decisions taken.",14);box.addView(result);AlertDialog d=new AlertDialog.Builder(this).setTitle("Test a path").setView(box).setNegativeButton("Close",null).setPositiveButton("Trace",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(v2->{int minute;try{String[] parts=at.getText().toString().split(":");int h=Integer.parseInt(parts[0]),m=Integer.parseInt(parts[1]);if(parts.length!=2||h<0||h>23||m<0||m>59)throw new IllegalArgumentException();minute=h*60+m;}catch(RuntimeException e){at.setError("Use HH:mm");return;}if(number.getText().toString().isBlank()){number.setError("Enter a number or sender");return;}String raw=number.getText().toString(),message=body==null?"":body.getText().toString();d.getButton(-1).setEnabled(false);Node snapshot=TreeStore.decode(TreeStore.encode(root));new Thread(()->{try{DecisionTree.Result trace=TreePolicy.evaluate(this,snapshot,sms,raw,message,minute,new CancellationSignal());runOnUiThread(()->{if(isDestroyed())return;canvas.highlight(trace);result.setText((sms?(trace.action()==ALLOW?"INBOX":"FILTERED"):trace.action().name())+" · "+trace.path().size()+" decisions\n"+trace.reason()+"\nClose to see the highlighted route.");d.getButton(-1).setEnabled(true);});}catch(RuntimeException e){runOnUiThread(()->{result.setText("Could not evaluate: "+e.getMessage());d.getButton(-1).setEnabled(true);});}},"tree-preview").start();}));d.show();}
    private String display(Node n){return sms&&n.kind==Kind.OUTCOME?(n.action==ALLOW?"Inbox":"Filtered"):title(n);}
    private void dialog(String title,LinearLayout box,Runnable apply){new AlertDialog.Builder(this).setTitle(title).setView(box).setNegativeButton("Cancel",null).setPositiveButton("Apply",(d,w)->apply.run()).show();}
    private void error(String message){new AlertDialog.Builder(this).setMessage(message).setPositiveButton("OK",null).show();}
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(8),dp(4),dp(8),dp(4));return l;}
    private TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xff16352e);t.setPadding(dp(6),dp(6),dp(6),dp(6));return t;}
    private Button button(LinearLayout p,String s,Runnable click){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(0xff087b60);b.setMinWidth(dp(48));b.setMinimumWidth(dp(48));b.setMinHeight(dp(48));b.setTextSize(13);android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(s.equals("Save")?0xff087b60:0xffe3ede8);bg.setCornerRadius(dp(12));b.setBackground(bg);b.setElevation(0);if(s.equals("Save"))b.setTextColor(Color.WHITE);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-2,dp(48));bp.setMargins(dp(3),dp(4),dp(3),dp(4));p.addView(b,bp);b.setOnClickListener(v->click.run());return b;}
    private EditText input(LinearLayout p,String hint,String value){EditText e=new EditText(this);e.setHint(hint);e.setText(value);e.setTextColor(0xff16352e);e.setSingleLine(true);p.addView(e,new LinearLayout.LayoutParams(-1,-2));return e;}
}
